#include <nlohmann/json.hpp>
#include <iostream>

int main() {
    try {
        nlohmann::json doc = nlohmann::json::parse("{\"a\": {\"bc\": 1, \"b\": 2}}");
        nlohmann::json patch = nlohmann::json::array({
            {{"op", "replace"}, {"path", "/a/b"}, {"value", 99}},
            {{"op", "replace"}, {"path", "/a/bc"}, {"value", 88}}
        });
        nlohmann::json res = doc.patch(patch);
        std::cout << "result: " << res.dump() << std::endl;
    } catch (const std::exception& e) {
        std::cout << "exception: " << e.what() << std::endl;
    }
    return 0;
}
